/* eslint-disable @typescript-eslint/no-unused-expressions, space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import indexOfTruthy = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	indexOfTruthy<number>( x ); // $ExpectType OutputArray
	indexOfTruthy<number>( x, 1 ); // $ExpectType OutputArray
	indexOfTruthy<number>( x, {} ); // $ExpectType OutputArray
	indexOfTruthy<number>( x, 1, {} ); // $ExpectType OutputArray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	indexOfTruthy( '5' ); // $ExpectError
	indexOfTruthy( 5 ); // $ExpectError
	indexOfTruthy( true ); // $ExpectError
	indexOfTruthy( false ); // $ExpectError
	indexOfTruthy( null ); // $ExpectError
	indexOfTruthy( void 0 ); // $ExpectError
	indexOfTruthy( {} ); // $ExpectError
	indexOfTruthy( ( x: number ): number => x ); // $ExpectError

	indexOfTruthy( '5', 0 ); // $ExpectError
	indexOfTruthy( 5, 0 ); // $ExpectError
	indexOfTruthy( true, 0 ); // $ExpectError
	indexOfTruthy( false, 0 ); // $ExpectError
	indexOfTruthy( null, 0 ); // $ExpectError
	indexOfTruthy( void 0, 0 ); // $ExpectError
	indexOfTruthy( {}, 0 ); // $ExpectError
	indexOfTruthy( ( x: number ): number => x, 0 ); // $ExpectError

	indexOfTruthy( '5', {} ); // $ExpectError
	indexOfTruthy( 5, {} ); // $ExpectError
	indexOfTruthy( true, {} ); // $ExpectError
	indexOfTruthy( false, {} ); // $ExpectError
	indexOfTruthy( null, {} ); // $ExpectError
	indexOfTruthy( void 0, {} ); // $ExpectError
	indexOfTruthy( {}, {} ); // $ExpectError
	indexOfTruthy( ( x: number ): number => x, {} ); // $ExpectError

	indexOfTruthy( '5', 0, {} ); // $ExpectError
	indexOfTruthy( 5, 0, {} ); // $ExpectError
	indexOfTruthy( true, 0, {} ); // $ExpectError
	indexOfTruthy( false, 0, {} ); // $ExpectError
	indexOfTruthy( null, 0, {} ); // $ExpectError
	indexOfTruthy( void 0, 0, {} ); // $ExpectError
	indexOfTruthy( {}, 0, {} ); // $ExpectError
	indexOfTruthy( ( x: number ): number => x, 0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a from index argument which is not an ndarray or an integer value...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	indexOfTruthy( x, '5' ); // $ExpectError
	indexOfTruthy( x, true ); // $ExpectError
	indexOfTruthy( x, false ); // $ExpectError
	indexOfTruthy( x, [] ); // $ExpectError
	indexOfTruthy( x, ( x: number ): number => x ); // $ExpectError

	indexOfTruthy( x, '5', {} ); // $ExpectError
	indexOfTruthy( x, true, {} ); // $ExpectError
	indexOfTruthy( x, false, {} ); // $ExpectError
	indexOfTruthy( x, [], {} ); // $ExpectError
	indexOfTruthy( x, ( x: number ): number => x, {} ); // $ExpectError
}

