	indexOfTruthy.assign( ( x: number ): number => x, y ); // $ExpectError

	indexOfTruthy.assign( '5', 0, y ); // $ExpectError
	indexOfTruthy.assign( 5, 0, y ); // $ExpectError
	indexOfTruthy.assign( true, 0, y ); // $ExpectError
	indexOfTruthy.assign( false, 0, y ); // $ExpectError
	indexOfTruthy.assign( null, 0, y ); // $ExpectError
	indexOfTruthy.assign( void 0, 0, y ); // $ExpectError
	indexOfTruthy.assign( {}, 0, y ); // $ExpectError
	indexOfTruthy.assign( ( x: number ): number => x, 0, y ); // $ExpectError

	indexOfTruthy.assign( '5', y, {} ); // $ExpectError
	indexOfTruthy.assign( 5, y, {} ); // $ExpectError
	indexOfTruthy.assign( true, y, {} ); // $ExpectError
	indexOfTruthy.assign( false, y, {} ); // $ExpectError
	indexOfTruthy.assign( null, y, {} ); // $ExpectError
	indexOfTruthy.assign( void 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( {}, y, {} ); // $ExpectError
	indexOfTruthy.assign( ( x: number ): number => x, y, {} ); // $ExpectError

	indexOfTruthy.assign( '5', 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( 5, 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( true, 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( false, 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( null, 0, y, {} ); // $ExpectError
	indexOfTruthy.assign( void 0, 0, y, {} ); // $ExpectError
